using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.AuditLogs.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.AuditLogs.Queries.GetAuditLogs;public sealed class GetAuditLogsQueryHandler(IAuditLogRepository repository):IRequestHandler<GetAuditLogsQuery,Result<IReadOnlyList<AuditLogDto>>>{public async Task<Result<IReadOnlyList<AuditLogDto>>>Handle(GetAuditLogsQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<AuditLogDto>>((await repository.GetAllAsync(request.UserId,request.EntityType,request.From,request.To,cancellationToken)).Select(AuditLogDto.FromEntity).ToList());}
